# Hypothesis for hidden_rule_fn
# TORVE rule: TORVE stays if nearest BLINX (Chebyshev, tie-break smaller) has splurn=1.
# TORVE moves toward nearest BLINX by 1 step per coord if splurn=0.
# BLINX rule (guess): BLINX moves toward nearest TORVE by 1 step per coord.
# If tie for nearest TORVE, pick smaller position.

def hidden_rule_fn(state):
    # Compute wrapped difference
    def wrap_diff(a, b):
        d = (b - a) % 8
        if d > 4:
            d = d - 8
        return d

    def chebyshev(a, b):
        return max(abs(wrap_diff(a[0], b[0])), abs(wrap_diff(a[1], b[1])))

    def splurn(p, q):
        return (p[0] + p[1] + q[0] + q[1]) % 2

    def direction_to(a, b):
        """Return (dx, dy) to move from a to b by one step in shortest direction."""
        dx = wrap_diff(a[0], b[0])
        dy = wrap_diff(a[1], b[1])
        # Normalize to -1, 0, +1
        if dx > 0:
            dx = 1
        elif dx < 0:
            dx = -1
        if dy > 0:
            dy = 1
        elif dy < 0:
            dy = -1
        return (dx, dy)

    # Separate TORVE and BLINX
    torves = [(i, p) for i, p in enumerate(state) if p['type'] == 'TORVE']
    blinx = [(i, p) for i, p in enumerate(state) if p['type'] == 'BLINX']

    next_state = []

    # Process each particle
    for i, p in enumerate(state):
        px, py = p['x'], p['y']
        ptype = p['type']

        if ptype == 'TORVE':
            # Find nearest BLINX by Chebyshev distance, tie-break by smaller position
            best_blinx = None
            best_dist = float('inf')
            for bi, bp in blinx:
                d = chebyshev((px, py), (bp['x'], bp['y']))
                if d < best_dist:
                    best_dist = d
                    best_blinx = bp
                elif d == best_dist:
                    # Tie-break: pick smaller position (lexicographically)
                    if (bp['x'], bp['y']) < (best_blinx['x'], best_blinx['y']):
                        best_blinx = bp

            if best_blinx is None:
                # No BLINX, TORVE stays
                next_state.append({'type': 'TORVE', 'x': px, 'y': py})
            else:
                s = splurn((px, py), (best_blinx['x'], best_blinx['y']))
                if s == 0:
                    # Move toward nearest BLINX
                    dx, dy = direction_to((px, py), (best_blinx['x'], best_blinx['y']))
                    nx = (px + dx) % 8
                    ny = (py + dy) % 8
                    next_state.append({'type': 'TORVE', 'x': nx, 'y': ny})
                else:
                    # Stay
                    next_state.append({'type': 'TORVE', 'x': px, 'y': py})

        elif ptype == 'BLINX':
            # Guess: BLINX moves toward nearest TORVE
            best_torve = None
            best_dist = float('inf')
            for ti, tp in torves:
                d = chebyshev((px, py), (tp['x'], tp['y']))
                if d < best_dist:
                    best_dist = d
                    best_torve = tp
                elif d == best_dist:
                    if (tp['x'], tp['y']) < (best_torve['x'], best_torve['y']):
                        best_torve = tp

            if best_torve is None:
                # No TORVE, BLINX stays? (unlikely based on training data)
                next_state.append({'type': 'BLINX', 'x': px, 'y': py})
            else:
                dx, dy = direction_to((px, py), (best_torve['x'], best_torve['y']))
                nx = (px + dx) % 8
                ny = (py + dy) % 8
                next_state.append({'type': 'BLINX', 'x': nx, 'y': ny})

    return next_state
